"""Named request contract metadata must retain the inputs fixed by core."""

import json
from copy import deepcopy
from pathlib import Path

import pytest

from ikigai.contract import contract_id, contract_iri
from ikigai.serve import ArgSpec, to_turtle

# These expectations were generated by Rust core, never by this face's hash.
VECTOR_DIR = Path(__file__).parent / "vectors"
VECTORS = json.loads((VECTOR_DIR / "fixed_contract_vectors.json").read_text(encoding="utf-8"))
EXISTING = json.loads((VECTOR_DIR / "contract_vectors.json").read_text(encoding="utf-8"))
CONTRACT = {case["name"]: case for case in EXISTING["contracts"]}


@pytest.mark.parametrize("value", ["urn:graph:one", "", 'a "quote"\nand a slash \\'])
def test_fixed_input_survives_json_round_trip(value):
    arg = {"name": "graph", "fixed": value}
    assert ArgSpec.of(arg).to_json()["fixed"] == value
    assert "fixed" not in ArgSpec("graph").to_json()


def test_fixed_input_changes_contract_identity():
    action = {"verb": "Source", "inputs": [{"name": "graph"}]}
    fixed = deepcopy(action)
    fixed["inputs"][0]["fixed"] = "urn:graph:one"
    assert contract_id("named-request", fixed) != contract_id("named-request", action)


def test_fixed_input_is_emitted_on_its_turtle_node():
    description = {
        "id": "named-request",
        "title": "",
        "summary": "",
        "verbs": ["Source", "Meta"],
        "inputs": [],
        "outputs": [],
        "actions": [
            {
                "verb": "Source",
                "inputs": [
                    {
                        "name": "graph",
                        "summary": "",
                        "required": True,
                        "source": "argument",
                        "fixed": "urn:graph:one",
                    },
                ],
            }
        ],
    }
    assert 'ik:fixed "urn:graph:one"' in to_turtle(description)


@pytest.mark.parametrize("case", VECTORS["contracts"], ids=lambda c: c["name"])
def test_fixed_contract_iri_matches_core(case):
    assert contract_iri(case["id"], case["action"]) == case["contract"]


@pytest.mark.parametrize("case", VECTORS["doors"], ids=lambda c: c["name"])
def test_fixed_contract_turtle_matches_core(case):
    assert to_turtle(case["description"]) == case["turtle"]


def test_unfixed_v1_and_v2_contracts_keep_their_existing_digests():
    for name in ["empty-source", "v2/needs"]:
        case = CONTRACT[name]
        action = deepcopy(case["action"])
        for arg in action.get("inputs", []):
            arg["fixed"] = None
        assert contract_iri(case["id"], action) == case["contract"]


def test_fixed_tail_is_a_set_independent_of_input_order_and_duplicates():
    case = next(c for c in VECTORS["contracts"] if c["name"] == "v2/fixed-two")
    action = deepcopy(case["action"])
    action["inputs"].reverse()
    action["inputs"].append(deepcopy(action["inputs"][0]))
    assert contract_iri(case["id"], action) == case["contract"]
